347:   <script>
348:     (() => {
349:       const canvas = document.getElementById('gameCanvas');
350:       const ctx = canvas.getContext('2d');
351:       const crosshair = document.getElementById('crosshair');
352:       const hud = document.getElementById('hud');
353:       const overlay = document.getElementById('overlay');
354:       const panel = document.getElementById('panel');
355:       const endScreen = document.getElementById('endScreen');
356: 
357:       const world = { w: 2200, h: 1600 };
358:       const keys = {};
359:       const pointer = { x: window.innerWidth / 2, y: window.innerHeight / 2, down: false };
360:       let dpr = 1;
361:       let camera = { x: 0, y: 0 };
362:       let lastTs = 0;
363:       let soundEnabled = true;
364:       let audioCtx = null;
365:       let state = {
366:         started: false,
367:         running: false,
368:         paused: false,
369:         dead: false,
370:         score: 0,
371:         kills: 0,
372:         wave: 1,
373:         spawnBudget: 7,
374:         spawnTimer: 0.5,
375:         wavePause: 0,
376:         toastTimer: 0,
377:         flash: 0,
378:         shake: 0,
379:         elapsed: 0,
380:       };
381: 
382:       const weapons = [
383:         { key: 'Pistol', maxMag: 12, reserve: 84, damage: 35, rate: 0.21, spread: 0.05, range: 640, pellets: 1, reload: 1.05 },
384:         { key: 'Shotgun', maxMag: 6, reserve: 42, damage: 18, rate: 0.7, spread: 0.28, range: 430, pellets: 7, reload: 1.25 },
385:         { key: 'Rifle', maxMag: 30, reserve: 180, damage: 22, rate: 0.11, spread: 0.045, range: 780, pellets: 1, reload: 1.5 }
386:       ];
387: 
388:       const player = {
389:         x: 1090,
390:         y: 820,
391:         r: 14,
392:         hp: 100,
393:         speed: 220,
394:         angle: 0,
395:         weapon: 0,
396:         mag: weapons[0].maxMag,
397:         reserve: weapons[0].reserve,
398:         fireCooldown: 0,
399:         reloadTimer: 0,
400:         invuln: 0,
401:       };
402: 
403:       let zombies = [];
404:       let bullets = [];
405:       let particles = [];
406:       let pickups = [];
407:       let decals = [];
408:       let obstacles = [];
409:       let props = [];
410:       let joystickVector = { x: 0, y: 0 };
411:       let joystickActive = false;
412:       let mobileFire = false;
413: 
414:       function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
415:       function rand(min, max) { return min + Math.random() * (max - min); }
416:       function dist(a, b) {
417:         return Math.hypot(a.x - b.x, a.y - b.y);
418:       }
419: 
420:       function resize() {
421:         dpr = Math.min(window.devicePixelRatio || 1, 2);
422:         canvas.width = Math.floor(innerWidth * dpr);
423:         canvas.height = Math.floor(innerHeight * dpr);
424:         canvas.style.width = innerWidth + 'px';
425:         canvas.style.height = innerHeight + 'px';
426:         ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
427:       }
428:       addEventListener('resize', resize);
429:       resize();
430: 
431:       function initAudio() {
432:         if (!audioCtx) {
433:           const Ctx = window.AudioContext || window.webkitAudioContext;
434:           if (Ctx) audioCtx = new Ctx();
435:         }
436:         if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
437:       }
438: 
439:       function playTone(freq = 150, duration = 0.06, type = 'square', volume = 0.015) {
440:         if (!soundEnabled || !audioCtx) return;
441:         const osc = audioCtx.createOscillator();
442:         const gain = audioCtx.createGain();
443:         osc.type = type;
444:         osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
445:         gain.gain.setValueAtTime(volume, audioCtx.currentTime);
446:         gain.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + duration);
447:         osc.connect(gain);
448:         gain.connect(audioCtx.destination);
449:         osc.start();
450:         osc.stop(audioCtx.currentTime + duration);
451:       }
452: 
453:       function showToast(text) {
454:         const el = document.getElementById('toast');
455:         el.textContent = text;
456:         el.classList.add('show');
457:         state.toastTimer = 1.5;
458:       }
459: 
460:       function updateHUD() {
461:         const w = weapons[player.weapon];
462:         document.getElementById('healthLabel').textContent = Math.max(0, Math.ceil(player.hp)) + '%';
463:         document.getElementById('healthBar').style.width = Math.max(0, player.hp) + '%';
464:         document.getElementById('magazine').textContent = String(player.mag).padStart(2, '0');
465:         document.getElementById('reserve').textContent = String(player.reserve).padStart(2, '0');
466:         document.getElementById('weaponName').textContent = w.key.toUpperCase();
467:         document.getElementById('scoreLabel').textContent = String(state.score).padStart(6, '0');
468:         document.getElementById('waveLabel').textContent = String(state.wave).padStart(2, '0');
469: 
470:         const threat = Math.min(100, zombies.length * 7 + state.wave * 8);
471:         document.getElementById('threatBar').style.width = threat + '%';
472:         document.getElementById('threatLabel').textContent = threat < 30 ? 'LOW' : threat < 65 ? 'ELEVATED' : 'CRITICAL';
473:       }
474: 
475:       function buildLevel() {
476:         obstacles = [];
477:         props = [];
478:         decals = [];
479:         pickups = [];
480: 
481:         for (let i = 0; i < 32; i++) {
482:           const x = rand(100, world.w - 100);
483:           const y = rand(100, world.h - 100);
484:           if (Math.hypot(x - 1100, y - 820) < 220) continue;
485:           const t = Math.random();
486:           if (t < 0.35) obstacles.push({ x, y, w: rand(90, 150), h: rand(34, 72), type: 'car', rot: rand(-0.2, 0.2) });
487:           else if (t < 0.7) obstacles.push({ x, y, w: rand(44, 80), h: rand(44, 92), type: 'crate', rot: 0 });
488:           else obstacles.push({ x, y, w: rand(90, 160), h: rand(24, 38), type: 'barrier', rot: rand(-0.12, 0.12) });
489:         }
490: 
491:         for (let i = 0; i < 120; i++) {
492:           props.push({ x: rand(40, world.w - 40), y: rand(40, world.h - 40), type: Math.random() < 0.65 ? 'weed' : 'debris', rot: rand(0, Math.PI * 2) });
493:         }
494: 
495:         for (let x = 180; x < world.w; x += 430) {
496:           for (let y = 200; y < world.h; y += 430) {
497:             props.push({ x, y, type: 'lamp', rot: 0 });
498:           }
499:         }
500:       }
501: 
502:       function resetGame() {
503:         state.started = true;
504:         state.running = true;
505:         state.paused = false;
506:         state.dead = false;
507:         state.score = 0;
508:         state.kills = 0;
509:         state.wave = 1;
510:         state.spawnBudget = 7;
511:         state.spawnTimer = 0.6;
512:         state.wavePause = 0;
513:         state.toastTimer = 0;
514:         state.flash = 0;
515:         state.shake = 0;
516:         state.elapsed = 0;
517: 
518:         player.x = 1090; player.y = 820; player.hp = 100; player.weapon = 0;
519:         player.mag = weapons[0].maxMag; player.reserve = weapons[0].reserve; player.fireCooldown = 0; player.reloadTimer = 0; player.invuln = 0; player.angle = 0;
520:         for (let i = 0; i < weapons.length; i++) { weapons[i].reserve = i === 0 ? 84 : i === 1 ? 42 : 180; }
521: 
522:         zombies = []; bullets = []; particles = []; pickups = []; decals = [];
523:         buildLevel();
524:         overlay.style.display = 'none';
525:         panel.classList.remove('show');
526:         endScreen.classList.remove('show');
527:         hud.style.display = 'block';
528:         showToast('Wave 01');
529:         updateHUD();
530:       }
531: 
532:       function switchWeapon(index) {
533:         if (index < 0 || index > 2) return;
534:         player.weapon = index;
535:         const w = weapons[index];
536:         // keep current mag as close as possible to the selected weapon's capacity without deleting total ammo
537:         if (player.mag > w.maxMag) player.mag = w.maxMag;
538:         player.fireCooldown = 0;
539:         player.reloadTimer = 0;
540:         updateHUD();
541:       }
542: 
543:       function reloadWeapon() {
544:         const w = weapons[player.weapon];
545:         if (player.reloadTimer > 0 || player.mag >= w.maxMag || player.reserve <= 0) return;
546:         player.reloadTimer = w.reload;
547:         playTone(330, 0.08, 'triangle', 0.018);
548:       }
549: 
550:       function spawnZombie() {
551:         const angle = rand(0, Math.PI * 2);
552:         const distance = Math.max(innerWidth, innerHeight) * 0.82 + rand(80, 260);
553:         const x = clamp(player.x + Math.cos(angle) * distance, 30, world.w - 30);
554:         const y = clamp(player.y + Math.sin(angle) * distance, 30, world.h - 30);
555:         const roll = Math.random();
556:         let type = 'walker';
557:         if (roll < Math.min(0.12 + state.wave * 0.018, 0.34)) type = 'runner';
558:         else if (roll < 0.14 + state.wave * 0.008) type = 'brute';
559: 
560:         const stats = {
561:           walker: { hp: 52, speed: 62, radius: 14, damage: 10 },
562:           runner: { hp: 40, speed: 96, radius: 12, damage: 10 },
563:           brute: { hp: 130, speed: 42, radius: 19, damage: 18 }
564:         }[type];
565: 
566:         zombies.push({
567:           x, y,
568:           hp: stats.hp + state.wave * 2,
569:           maxHp: stats.hp + state.wave * 2,
570:           speed: stats.speed + state.wave * 2.1,
571:           radius: stats.radius,
572:           damage: stats.damage,
573:           type,
574:           angle: 0,
575:           hitFlash: 0,
576:           attackCooldown: rand(0.2, 0.8),
577:           phase: rand(0, 10),
578:         });
579:       }
580: 
581:       function emitParticles(x, y, color, count = 8, speed = 120) {
582:         for (let i = 0; i < count; i++) {
583:           const a = rand(0, Math.PI * 2);
584:           const v = rand(speed * 0.25, speed);
585:           particles.push({ x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, life: rand(0.18, 0.55), maxLife: 0.55, color, size: rand(2, 5) });
586:         }
587:       }
588: 
589:       function addPickup(x, y) {
590:         if (Math.random() < 0.12) {
591:           pickups.push({ x, y, type: (Math.random() < 0.5 ? 'ammo' : 'med'), life: 18, pulse: rand(0, Math.PI * 2) });
592:         }
593:       }
594: 
595:       function killZombie(z) {
596:         const idx = zombies.indexOf(z);
597:         if (idx >= 0) zombies.splice(idx, 1);
598:         state.score += z.type === 'brute' ? 250 : z.type === 'runner' ? 160 : 100;
599:         state.kills += 1;
600:         decals.push({ x: z.x, y: z.y, radius: rand(12, 22), alpha: rand(0.5, 0.8) });
601:         emitParticles(z.x, z.y, '#d35a46', 13, 150);
602:         addPickup(z.x, z.y);
603:         updateHUD();
604:       }
