606:       function shoot() {
607:         if (player.fireCooldown > 0 || player.reloadTimer > 0) return;
608:         const w = weapons[player.weapon];
609:         if (player.mag <= 0) {
610:           reloadWeapon();
611:           playTone(90, 0.05, 'square', 0.02);
612:           return;
613:         }
614: 
615:         player.mag -= 1;
616:         player.fireCooldown = w.rate;
617:         state.shake = Math.max(state.shake, player.weapon === 1 ? 9 : player.weapon === 2 ? 4 : 3);
618:         state.flash = 0.08;
619:         playTone(player.weapon === 1 ? 78 : player.weapon === 2 ? 106 : 144, player.weapon === 1 ? 0.14 : 0.08, player.weapon === 1 ? 'sawtooth' : 'square', player.weapon === 1 ? 0.04 : 0.025);
620: 
621:         const target = (window.innerWidth < 760) ?
622:           zombies.reduce((best, z) => {
623:             const d = dist(player, z);
624:             return d < 640 && (!best || d < best.d) ? { z, d } : best;
625:           }, null) : null;
626: 
627:         let aim = player.angle;
628:         if (target) aim = Math.atan2(target.z.y - player.y, target.z.x - player.x);
629:         else aim = Math.atan2(pointer.y - innerHeight / 2, pointer.x - innerWidth / 2);
630:         player.angle = aim;
631: 
632:         for (let p = 0; p < w.pellets; p++) {
633:           const spreadAngle = aim + rand(-w.spread, w.spread);
634:           const dx = Math.cos(spreadAngle);
635:           const dy = Math.sin(spreadAngle);
636:           let bestHit = null;
637:           let closestDist = w.range;
638: 
639:           for (const z of zombies) {
640:             const vx = z.x - player.x;
641:             const vy = z.y - player.y;
642:             const proj = vx * dx + vy * dy;
643:             if (proj < 0 || proj > w.range) continue;
644:             const side = Math.abs(vx * dy - vy * dx);
645:             if (side < z.radius + 4) {
646:               if (proj < closestDist) {
647:                 closestDist = proj;
648:                 bestHit = z;
649:               }
650:             }
651:           }
652: 
653:           if (bestHit) {
654:             bestHit.hp -= w.damage;
655:             bestHit.hitFlash = 0.12;
656:             emitParticles(bestHit.x, bestHit.y, '#d95d49', 5, 60);
657:             if (bestHit.hp <= 0) killZombie(bestHit);
658:           } else {
659:             const endX = player.x + dx * rand(w.range * 0.55, w.range);
660:             const endY = player.y + dy * rand(w.range * 0.55, w.range);
661:             bullets.push({ x: player.x + dx * 18, y: player.y + dy * 18, endX, endY, life: 0.08, color: player.weapon === 1 ? '#f0a166' : '#e7e9ae' });
662:           }
663:         }
664: 
665:         updateHUD();
666:       }
