668:       function handleInput(dt) {
669:         let moveX = 0;
670:         let moveY = 0;
671: 
672:         const kbX = Number(Boolean(keys.KeyD || keys.ArrowRight)) - Number(Boolean(keys.KeyA || keys.ArrowLeft));
673:         const kbY = Number(Boolean(keys.KeyS || keys.ArrowDown)) - Number(Boolean(keys.KeyW || keys.ArrowUp));
674: 
675:         if (Math.abs(kbX) || Math.abs(kbY)) {
676:           const len = Math.hypot(kbX, kbY); moveX = kbX / len; moveY = kbY / len;
677:         }
678: 
679:         if (Math.abs(joystickVector.x) || Math.abs(joystickVector.y)) {
680:           moveX += joystickVector.x; moveY += joystickVector.y;
681:         }
682: 
683:         const len = Math.hypot(moveX, moveY);
684:         if (len > 1) { moveX /= len; moveY /= len; }
685: 
686:         const nx = player.x + moveX * player.speed * dt;
687:         const ny = player.y + moveY * player.speed * dt;
688:         player.x = clamp(nx, 18, world.w - 18);
689:         player.y = clamp(ny, 18, world.h - 18);
690: 
691:         for (const o of obstacles) {
692:           const dx = player.x - o.x;
693:           const dy = player.y - o.y;
694:           const rx = o.w / 2 + player.r;
695:           const ry = o.h / 2 + player.r;
696:           if (Math.abs(dx) < rx && Math.abs(dy) < ry) {
697:             const ox = rx - Math.abs(dx);
698:             const oy = ry - Math.abs(dy);
699:             if (ox < oy) player.x += Math.sign(dx || 1) * ox;
700:             else player.y += Math.sign(dy || 1) * oy;
701:           }
702:         }
703: 
704:         camera.x = clamp(player.x - innerWidth / 2, 0, world.w - innerWidth);
705:         camera.y = clamp(player.y - innerHeight / 2, 0, world.h - innerHeight);
706: 
707:         if (window.innerWidth >= 760) {
708:           player.angle = Math.atan2(pointer.y - innerHeight / 2, pointer.x - innerWidth / 2);
709:         }
710: 
711:         if (pointer.down || mobileFire) shoot();
712:       }
