714:       function gameOver() {
715:         state.running = false;
716:         state.dead = true;
717:         pointer.down = false;
718:         document.getElementById('endTitle').textContent = 'Hold the line.';
719:         document.getElementById('endText').textContent = 'Dawn is still far off. You survived longer than most.';
720:         document.getElementById('finalStats').textContent = 'Wave ' + String(state.wave).padStart(2, '0') + ' · ' + state.kills + ' infected · ' + String(state.score).padStart(6, '0') + ' pts';
721:         endScreen.classList.add('show');
