724:       function updateGame(dt) {
725:         state.elapsed += dt;
726:         if (state.toastTimer > 0) {
727:           state.toastTimer -= dt;
728:           if (state.toastTimer <= 0) document.getElementById('toast').classList.remove('show');
729:         }
730: 
731:         player.fireCooldown = Math.max(0, player.fireCooldown - dt);
732:         player.invuln = Math.max(0, player.invuln - dt);
733: 
734:         if (player.reloadTimer > 0) {
735:           player.reloadTimer -= dt;
736:           if (player.reloadTimer <= 0) {
737:             const w = weapons[player.weapon];
738:             const needed = w.maxMag - player.mag;
739:             const load = Math.min(needed, player.reserve);
740:             player.mag += load;
741:             player.reserve -= load;
742:             playTone(520, 0.07, 'triangle', 0.018);
743:             updateHUD();
744:           }
745:         }
746: 
747:         handleInput(dt);
748: 
749:         if (state.started && state.running && !state.paused && !state.dead) {
750:           if (zombies.length < state.spawnBudget) {
751:             state.spawnTimer -= dt;
752:             if (state.spawnTimer <= 0) {
753:               spawnZombie();
754:               state.spawnTimer = Math.max(0.26, 1.15 - state.wave * 0.05);
755:             }
756:           }
757: 
758:           if (zombies.length === 0 && state.spawnBudget <= 0 && !state.dead) {
759:             state.wavePause += dt;
760:             if (state.wavePause > 2.6) {
761:               state.wave += 1;
762:               state.spawnBudget = 5 + state.wave * 3;
763:               state.wavePause = 0;
764:               state.spawnTimer = 0.5;
765:               player.hp = Math.min(100, player.hp + 10);
766:               for (const w of weapons) w.reserve += Math.ceil(w.reserve * 0.12);
767:               showToast('Wave ' + String(state.wave).padStart(2, '0'));
768:               updateHUD();
769:             }
770:           } else if (zombies.length > 0) {
771:             state.wavePause = 0;
772:           }
773:         }
774: 
775:         for (const z of zombies) {
776:           z.phase += dt * 6;
777:           z.hitFlash = Math.max(0, z.hitFlash - dt);
778:           const dx = player.x - z.x;
779:           const dy = player.y - z.y;
780:           const distance = Math.hypot(dx, dy) || 1;
781:           z.angle = Math.atan2(dy, dx);
782: 
783:           if (distance > z.radius + player.r + 8) {
784:             const sx = (dx / distance) * z.speed * dt;
785:             const sy = (dy / distance) * z.speed * dt;
786:             let nx = z.x + sx;
787:             let ny = z.y + sy;
788: 
789:             let blocked = false;
790:             for (const o of obstacles) {
791:               if (Math.abs(nx - o.x) < o.w / 2 + z.radius && Math.abs(ny - o.y) < o.h / 2 + z.radius) {
792:                 blocked = true;
793:                 nx = z.x;
794:                 ny = z.y;
795:                 break;
796:               }
797:             }
798: 
799:             if (!blocked) {
800:               z.x = nx;
801:               z.y = ny;
802:             }
803:           } else {
804:             z.attackCooldown -= dt;
805:             if (z.attackCooldown <= 0 && player.invuln <= 0) {
806:               z.attackCooldown = 0.76;
807:               player.hp -= z.damage;
808:               player.invuln = 0.5;
809:               state.shake = 12;
810:               state.flash = 0.16;
811:               emitParticles(player.x, player.y, '#e3594c', 8, 80);
812:               playTone(64, 0.18, 'sawtooth', 0.04);
813:               if (player.hp <= 0) {
814:                 player.hp = 0;
815:                 gameOver();
816:                 updateHUD();
817:                 return;
818:               }
819:               updateHUD();
820:             }
821:           }
822:         }
823: 
824:         for (const p of particles) {
825:           p.x += p.vx * dt;
826:           p.y += p.vy * dt;
827:           p.life -= dt;
828:           p.vx *= 0.96;
829:           p.vy *= 0.96;
830:         }
831:         for (let i = particles.length - 1; i >= 0; i--) if (particles[i].life <= 0) particles.splice(i, 1);
832: 
833:         for (const b of bullets) b.life -= dt;
834:         for (let i = bullets.length - 1; i >= 0; i--) if (bullets[i].life <= 0) bullets.splice(i, 1);
835: 
836:         for (const p of pickups) {
837:           p.life -= dt;
838:           p.pulse += dt * 7;
839:           if (dist(p, player) < 30) {
840:             if (p.type === 'med') player.hp = Math.min(100, player.hp + 25);
841:             else {
842:               for (const w of weapons) w.reserve += w.key === 'Shotgun' ? 8 : w.key === 'Rifle' ? 24 : 12;
843:             }
844:             state.score += 25;
845:             emitParticles(p.x, p.y, p.type === 'med' ? '#d9f86c' : '#d7c58c', 9, 70);
846:             p.life = 0;
847:           }
848:         }
849:         for (let i = pickups.length - 1; i >= 0; i--) if (pickups[i].life <= 0) pickups.splice(i, 1);
850: 
851:         if (state.started && state.running && !state.dead && zombies.length === 0 && state.spawnBudget <= 0) {
852:           state.spawnBudget = 0;
853:         }
854: 
855:         state.shake = Math.max(0, state.shake - dt * 24);
856:         state.flash = Math.max(0, state.flash - dt * 3);
857:         updateHUD();
858:       }
