969:         ctx.fillStyle = skin; ctx.beginPath(); ctx.arc(z.radius * 0.5, -1, z.radius * 0.42, 0, Math.PI * 2); ctx.fill();
970:         ctx.fillStyle = '#b85c42'; ctx.beginPath(); ctx.arc(z.radius * 0.62, -z.radius * 0.15, 2, 0, Math.PI * 2); ctx.fill();
