function switchWeapon(index) {
  if (index < 0 || index > 2) return;
  player.weapon = index;
  const w = weapons[index];
  // keep current mag as close as possible to the selected weapon's capacity without deleting total ammo
  if (player.mag > w.maxMag) player.mag = w.maxMag;
  player.fireCooldown = 0;
  player.reloadTimer = 0;
  updateHUD();
}

